const body = $input.first().json.body || $input.first().json;
const query = $input.first().json.query || {};

let instance = query.instance;
if (!instance) {
  const inboxId = body.inbox?.id;
  if (inboxId === 16) instance = 'lat-whatscol';
  else if (inboxId === 18) instance = '3059861096';
  else if (inboxId === 4) instance = 'TTvAlertsMovistar';
  else instance = body.inbox?.name;
}

const cleanText = (str) => {
  if (!str || typeof str !== 'string') return str;
  return str
    .replace(/\\+(\r?\n|$)/g, '$1')
    .replace(/^[ \t]*\\+[ \t]*$/gm, '');
};

if (body.content) {
  body.content = cleanText(body.content);
}

if (body.conversation?.messages && Array.isArray(body.conversation.messages)) {
  for (const m of body.conversation.messages) {
    if (m.content) {
      m.content = cleanText(m.content);
    }
  }
}

const evolutionBase = 'https://project1-evolution-api.efebpb.easypanel.host';
const targetUrl = `${evolutionBase}/chatwoot/webhook/${instance}`;

let evolutionResponse = { message: 'bot' };
try {
  evolutionResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: targetUrl,
    headers: {
      'Content-Type': 'application/json'
    },
    body: body,
    json: true
  });
} catch (err) {
  evolutionResponse = { message: 'forwarded_error', error: err.message };
}

return [{
  json: {
    response: evolutionResponse,
    instance: instance,
    event: body.event,
    message_id: body.id
  }
}];
